import{_ as e}from"./chunks/projects.BdG50VF9.js";import{_ as t,c as r,o,a2 as i}from"./chunks/framework.CIiVzG-O.js";const m=JSON.parse('{"title":"コミットする前に","description":"プロジェクトフォルダ内の変更されたファイルをすべて確認し、qDiff から離れずにコミットします。","frontmatter":{"title":"コミットする前に","description":"プロジェクトフォルダ内の変更されたファイルをすべて確認し、qDiff から離れずにコミットします。"},"headers":[],"relativePath":"ja/guide/projects.md","filePath":"ja/guide/projects.md","lastUpdated":1794296122000}'),s={name:"ja/guide/projects.md"};function l(p,a,c,d,n,h){return o(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="コミットする前に" tabindex="-1">コミットする前に <a class="header-anchor" href="#コミットする前に" aria-label="Permalink to &quot;コミットする前に&quot;">​</a></h1><p>コミットの前に「自分は実際に何を変えたのか？」をひと確認しておくと安心です。 qDiff でプロジェクトフォルダを開けば、その答えはすでに目の前に並んでいます。</p><img src="'+e+'" alt="色分けされた差分の横に並んだ変更ファイルの一覧" class="guide-shot"><h2 id="プロジェクトフォルダを開く" tabindex="-1">プロジェクトフォルダを開く <a class="header-anchor" href="#プロジェクトフォルダを開く" aria-label="Permalink to &quot;プロジェクトフォルダを開く&quot;">​</a></h2><p><strong>ファイル → 開く</strong>から Git プロジェクトのフォルダを選ぶか、ウィンドウに ドラッグします。qDiff が編集したファイルを 1 つの一覧にまとめます。</p><h2 id="一覧を見てから、変更を読む" tabindex="-1">一覧を見てから、変更を読む <a class="header-anchor" href="#一覧を見てから、変更を読む" aria-label="Permalink to &quot;一覧を見てから、変更を読む&quot;">​</a></h2><p>各ファイルには、新規・変更・削除のいずれが起きたかが印で示されます。1 つ クリックすると、右側に中身の変更がそのまま表示されます。色や語単位の ハイライトは、通常のファイル比較と同じです。</p><p>順に 1 つずつ見ていきましょう。一覧が現在位置を保持してくれるので、長い レビューでも見落としがありません。</p><h2 id="同じウィンドウで完了する" tabindex="-1">同じウィンドウで完了する <a class="header-anchor" href="#同じウィンドウで完了する" aria-label="Permalink to &quot;同じウィンドウで完了する&quot;">​</a></h2><p>すべて問題なければ、ここからコミットできます。更新・プッシュ・取り消し・ 競合の解消も、比較画面から離れずに行えます。他のアプリを開く必要も、 アカウントも不要です。</p><div class="tip custom-block"><p class="custom-block-title">プロジェクトフォルダではない場合</p><p>普通のフォルダは、これまでどおり通常のフォルダ比較として開きます。 <a href="./folders.html">フォルダの比較</a>はどこでも使えます。</p></div><p>次は<a href="./more.html">画像、アーカイブ、その他の比較</a>へ。</p>',12)])])}const u=t(s,[["render",l]]);export{m as __pageData,u as default};
